import numpy as np


def amdahl_speedup(serial_fraction: float, num_workers: int) -> float:
    s = float(serial_fraction)
    p = int(num_workers)
    return float(1.0 / (s + (1.0 - s) / p))


def _single_matmul_checksum(pair: tuple[np.ndarray, np.ndarray]) -> float:
    a_2d, b_2d = pair
    return float(np.sum(a_2d @ b_2d, dtype=np.float64))


def parallel_matmul_checksums(
    tasks: list[tuple[np.ndarray, np.ndarray]],
    num_workers: int,
) -> list[float]:
    if num_workers <= 1:
        return [_single_matmul_checksum(pair) for pair in tasks]
    with mp.Pool(processes=int(num_workers)) as pool:
        return [float(x) for x in pool.map(_single_matmul_checksum, tasks)]

