def naive_matmul_step(A, B, out, tile):
    for i in range(A.shape[0]):
        for j in range(B.shape[1]):
            out[i, j] = sum(A[i, k] * B[k, j] for k in range(A.shape[1]))


def tiled_matmul_step(A, B, out, tile):
    left = A.scratch((tile, tile))
    right = B.scratch((tile, tile))
    for row in range(0, A.shape[0], tile):
        for col in range(0, B.shape[1], tile):
            acc = [[0.0] * tile for _ in range(tile)]
            for base in range(0, A.shape[1], tile):
                for i in range(tile):
                    for j in range(tile):
                        left[i, j] = A[row+i, base+j]
                        right[i, j] = B[base+i, col+j]
                for i in range(tile):
                    for j in range(tile):
                        acc[i][j] += sum(left[i, k] * right[k, j] for k in range(tile))
            for i in range(tile):
                for j in range(tile):
                    out[row+i, col+j] = acc[i][j]

