    return hidden @ w2, {"x": x, "hidden": hidden}


def cache_bytes(cache):
    return sum(t.numel() * t.element_size() for t in cache.values())

def train_ledger(model, optimizer):
    def size(t):
        return t.numel() * t.element_size()
    states = optimizer.state.values()
    return [sum(size(p) for p in model.parameters()),
            sum(size(p.grad) for p in model.parameters()),
            sum(size(s[k]) for s in states for k in ("exp_avg", "exp_avg_sq")),
            sum(size(s["step"]) for s in states)]

import torch


def fp16_underflow_grad(grad):
    return torch.tensor(grad, dtype=torch.float16).item()


def loss_scaled_step(weight, grad, lr, scale):
    scaled = torch.tensor(grad * scale, dtype=torch.float16)
    if not torch.isfinite(scaled):
        return weight
    return (torch.tensor(weight, dtype=torch.float32) - lr * (scaled.float() / scale)).item()


def dynamic_scaler_update(scale, found_inf):
    return max(1, scale / 2) if found_inf else min(65536, scale * 2)

import math
import torch


def online_softmax_update(m_prev, l_prev, block_scores):
    m = max(m_prev, block_scores.max().item())
    weights = torch.exp(block_scores - m)
    return m, l_prev * math.exp(m_prev - m) + weights.sum().item()


def online_attention_step(m_prev, l_prev, o_prev, block_scores, block_v):
    m, l = online_softmax_update(m_prev, l_prev, block_scores)
    o = o_prev * math.exp(m_prev - m) + torch.exp(block_scores - m) @ block_v
    return m, l, o


def tiled_attention(Q, K, V, block_size):
    rows = []
    for q in Q:
        m, l, o = -math.inf, 0.0, V.new_zeros(V.shape[1])
        for i in range(0, len(K), block_size):
            scores = K[i:i+block_size] @ q / math.sqrt(q.numel())
            m, l, o = online_attention_step(m, l, o, scores, V[i:i+block_size])
        rows.append(o / l)
    return torch.stack(rows)

def bucket_timeline(ready_ms, sizes, cap, alpha_ms, bytes_per_ms):
    timeline = []
    used = 0
    for i, size in enumerate(sizes):
        used += size
        if i+1 == len(sizes) or used + sizes[i+1] > cap:
            start = max(ready_ms[i], timeline[-1][1] if timeline else 0)
            timeline.append([start, start + alpha_ms + used / bytes_per_ms, used])
            used = 0
    return timeline

def allocate_sequence(state, name, tokens):
    if name in state["seq"]:
        raise KeyError(name)
    needed = (len(tokens)+15)//16
    if len(state["free"]) < needed:
        raise MemoryError
    blocks = []
    for start in range(0, len(tokens), 16):
        page = state["free"].pop()
        blocks.append(page)
        state["refs"][page] = 1
        chunk = tokens[start:start+16]
        state["pages"][page][:len(chunk)] = chunk
    state["seq"][name] = {"length":len(tokens), "blocks":blocks}


def append_token(state, name, token):
    seq = state["seq"][name]
    block, offset = divmod(seq["length"],16)
    table = seq["blocks"]
    if offset == 0 or state["refs"][table[block]] > 1:
        if not state["free"]:
            raise MemoryError
        page = state["free"].pop()
        state["refs"][page] = 1
        if offset:
            old = table[block]
            state["pages"][page][:] = state["pages"][old]
            state["refs"][old] -= 1
            table[block] = page
        else:
            table.append(page)
    state["pages"][table[block]][offset] = token
    seq["length"] += 1


def free_sequence(state, name):
    for page in state["seq"].pop(name)["blocks"]:
        state["refs"][page] -= 1
        if state["refs"][page] == 0:
            state["free"].append(page)


def fork_prefix(state, parent, child, length):
    if child in state["seq"]:
        raise KeyError(child)
    src = state["seq"][parent]
    if not 0 <= length <= src["length"]:
        raise ValueError(length)
    table = src["blocks"][:(length+15)//16]
    for page in table:
        state["refs"][page] += 1
    state["seq"][child] = {"length":length,"blocks":table}

import torch


def quantize_int4_grouped(w, group):
    scales, codes = [], []
    for chunk in w.split(group):
        scale = chunk.abs().max().item()/7 or 1.0
        scales.append(scale)
        codes.extend((chunk/scale).round().clamp(-7,7).int().tolist())
    if len(codes)%2:
        codes.append(0)
    packed = [(codes[i]&15) | ((codes[i+1]&15)<<4) for i in range(0,len(codes),2)]
    return torch.tensor(packed,dtype=torch.uint8), torch.tensor(scales)


def dequantize_int4_grouped(packed, scales, group, length):
    out = []
    for i in range(length):
        value = (packed[i//2].item() >> (4*(i%2))) & 15
        signed = value-16 if value >= 8 else value
        out.append(signed * scales[i//group].item())
    return torch.tensor(out)
